  const lines = [`${id}: differs in ${facts.join(', ')}`]
  lines.push(`  go:   ${go.text}`, `  tsrs: ${tsrs.text}`)
  if (facts.includes('flags') || facts.includes('intrinsicName')) {
    lines.push(
