export function compareCaptures(go: Capture, tsrs: Capture, allowlist: Allowlist): ParityResult {
  const ids = [...new Set([...Object.keys(go), ...Object.keys(tsrs)])].toSorted()
  const result: ParityResult = {
    rows: ids.length,
    identical: 0,
    unexpected: [],
    allowed: [],
    staleAllowed: [],
    missing: [],
